-- Blog: guides for buyers and sellers, written and edited by staff in the
-- back office. body is the same block list the help center uses:
-- [{"p": "..."}, {"h": "..."}, {"list": [...]}, {"note": "..."}, {"links": [{"label","href","text"}]}].
-- Text may use {fee.flat}, {fee.threshold}, {fee.percent} and {fee.cap},
-- filled from the live fee schedule when the page is shown.
CREATE TABLE blog_posts (
    id            SERIAL PRIMARY KEY,
    slug          TEXT NOT NULL CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND char_length(slug) <= 100),
    title         TEXT NOT NULL CHECK (char_length(title) BETWEEN 5 AND 140),
    description   TEXT NOT NULL DEFAULT '' CHECK (char_length(description) <= 300),
    keyword       TEXT NOT NULL DEFAULT '' CHECK (char_length(keyword) <= 120),
    intro         TEXT NOT NULL DEFAULT '' CHECK (char_length(intro) <= 2000),
    body          JSONB NOT NULL DEFAULT '[]',
    status        TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
    published_at  TIMESTAMPTZ,
    created_by    UUID REFERENCES users (id) ON DELETE SET NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX blog_posts_slug ON blog_posts (slug);
CREATE INDEX blog_posts_published ON blog_posts (published_at DESC) WHERE status = 'published';

-- The first four guides.
INSERT INTO blog_posts (slug, title, description, keyword, intro, body, status, published_at) VALUES
('buy-sports-card-singles-online', 'How to Buy Sports Card Singles Online (Without Overpaying)', 'A buyer''s guide to sports card singles online: finding the exact card, raw vs. graded, checking condition and sellers, and paying safely with free shipping.', 'buy sports card singles online', 'Buying single cards is the fastest way to finish a set, chase a favorite player, or pick up a rookie before he breaks out. Ripping packs is fun, but if you want one specific card, buying the single almost always costs less than chasing it. Here''s how to buy sports card singles online with confidence, and how to avoid the mistakes that cost collectors money.', '[{"h":"Why buy singles instead of packs?"},{"p":"A hobby box can cost hundreds of dollars, and the card you want might be one in several thousand packs. When you buy the single, you pay for exactly the card you want, in the condition you want, and you can see it before you buy. That''s why most serious collectors build their personal collections, and their player and team runs, from singles."},{"h":"1. Know exactly which card you want"},{"p":"Sports cards come in many versions of the same player and year, and the price difference between them can be huge. Before you search, write down:"},{"list":["Year and set (for example, 2018 Topps Update or 2023 Panini Prizm).","Card number, printed on the back. It separates the base card from inserts with the same photo.","Parallel or variation: Silver, Refractor, numbered /99, short print, image variation.","Rookie Card (RC), autograph or memorabilia, if that''s what you''re after."]},{"p":"On Slabs & Singles you can search by player and narrow by sport, year, set, card number, grader, grade, condition and price, so you see only the version you mean. Saved searches email or notify you when a new match is listed."},{"links":[{"label":"Shop sports cards","href":"/sports","text":"baseball, basketball, football, hockey, soccer and more."},{"label":"Advanced search","href":"/search","text":"filter by year, set, card number, grade and price."}]},{"h":"2. Raw or graded?"},{"p":"A raw card is ungraded: you judge its condition from the photos. A graded card has been authenticated and scored by a grading company and sealed in a plastic case (a slab), with a certification number."},{"list":["Buy raw when the card is inexpensive, when you want to judge it yourself, or when you plan to submit it for grading.","Buy graded when the card is valuable, when condition makes a big difference to the price, or when you want proof it''s authentic.","Graded cards on Slabs & Singles show the grading company (PSA, BGS, SGC, CGC or TAG), the grade and the cert number. Look the cert up on the grader''s website before you buy an expensive slab."]},{"h":"3. Read the condition, then look at the photos"},{"p":"Raw cards are listed as Near Mint (NM), Lightly Played (LP), Moderately Played (MP), Heavily Played (HP) or Damaged (DMG). Every seller is asked for clear photos of the front and back. Zoom in on four things:"},{"list":["Corners: sharp, or rounded and soft?","Edges: clean, or chipped (common on dark borders)?","Surface: scratches, print lines, dents or creases. Tilt-shot photos help.","Centering: are the borders even left to right and top to bottom?"]},{"p":"If something isn''t clear, message the seller from the listing before you buy."},{"h":"4. Check the seller"},{"p":"Every seller has a public feedback score and a percentage of positive ratings over the last year. Seller badges show experience at a glance: Bronze through Diamond for sales completed, and Top Rated for sellers with great feedback who ship on time. New sellers start with a $20 price limit per card and earn higher limits as they build a record, so an expensive card is always sold by an established seller."},{"h":"5. Compare the real price, shipping included"},{"p":"On many sites the price you see isn''t the price you pay: a $3 card can turn into an $8 card at checkout once shipping is added. On Slabs & Singles every card ships free, so the price on the listing is the price you pay (plus sales tax where it applies)."},{"p":"Buying several cards from one seller? They ship together, and many sellers offer a multi-card discount that''s taken off automatically in your cart. Some sellers also run store-wide sales, shown with the regular price crossed out."},{"h":"6. Make an offer or bid"},{"p":"Listings marked “or Best Offer” let you offer less than the asking price; the seller can accept, counter or decline. Auctions use proxy bidding: enter the most you''ll pay and the site bids for you only as much as needed to keep you in the lead."},{"h":"7. Pay safely"},{"p":"Always pay on the site. On Slabs & Singles you pay by card through Stripe, which keeps your card issuer''s purchase protection. Never pay a seller through Venmo, Zelle, Cash App or PayPal Friends & Family for a card listed online; it''s the most common way card buyers get scammed. Messages that include payment apps or contact details aren''t delivered."},{"h":"8. When your card arrives"},{"p":"Sellers ship within 3 business days. Graded cards and cards over $20 ship in a padded mailer with tracking. Check the card against the listing when it arrives, and leave feedback: it helps the next buyer and rewards good sellers. If something is wrong, message the seller from your order first; most problems are solved quickly."},{"h":"Quick checklist"},{"list":["Exact year, set, card number and parallel written down.","Raw or graded decided, and the cert checked for an expensive slab.","Front and back photos checked for corners, edges, surface and centering.","Seller''s feedback and badges checked.","Total price compared with shipping included.","Paid on the site, never off-platform."]},{"links":[{"label":"Start shopping sports card singles","href":"/sports"},{"label":"Graded slabs for sale","href":"/search?min_grade=1"},{"label":"Cards under $5","href":"/search?max_price=5&sort=price_asc"}]}]'::jsonb, 'published', '2026-11-05T12:00:00Z'),
('where-to-sell-graded-sports-cards-online', 'Where to Sell Graded Sports Cards Online: Fees, Safety and Shipping Compared', 'Where to sell graded sports cards online: what each type of site costs, how to price a slab, and how to ship PSA, BGS and SGC cards safely.', 'where to sell graded sports cards online', 'You paid to grade the card, waited weeks for it to come back, and now it''s in a slab with a number on it. Where you sell it decides how much of the sale you keep, how fast it sells, and how safe the sale is. Here''s how the main options compare, and what to look for in any site you list on.', '[{"h":"The main places to sell graded cards"},{"list":["Large general marketplaces (like eBay): the biggest audience, but fees for trading cards are typically over 13% of the sale plus a per-order fee, and your slab competes with millions of other listings.","Auction houses: good for very high-end cards, but they take a commission from both the buyer and the seller, and payment can take weeks.","Consignment services: they photograph, list and ship for you, in exchange for a larger cut of the sale.","Card shops and shows: instant cash, but dealers buy below market value so they can resell at a profit.","Card-only marketplaces like Slabs & Singles: buyers who are there for cards, lower fees, and tools built around grading, cert numbers and slab shipping."]},{"h":"What to compare before you list"},{"h":"1. What you actually keep"},{"p":"Add up every fee: the site''s selling fee, payment processing, and shipping. On a $150 PSA 10, a few percentage points is real money."},{"p":"On Slabs & Singles, listing is free. There''s one fee per card sold: {fee.flat} for cards up to {fee.threshold}, and {fee.percent} for cards over {fee.threshold}, capped at {fee.cap} per card. Stripe''s card processing (usually 2.9% + 30¢ per order) comes out of your own Stripe balance. There are no insertion fees, subscriptions or ad fees to sell."},{"links":[{"label":"Selling fees in detail","href":"/help/fees"}]},{"h":"2. Who gets paid, and when"},{"p":"On Slabs & Singles buyers pay you directly through your own Stripe account; the marketplace never holds your money. Stripe pays out to your bank on its normal schedule."},{"h":"3. Buyer trust"},{"p":"Graded cards sell faster when buyers can verify them. Every graded listing here shows the grading company (PSA, BGS, SGC, CGC or TAG), the grade and the certification number, so buyers can look the cert up before they buy. Seller badges, feedback and seller levels (new sellers start at a $20 limit per card and work up to $1,000) show buyers that expensive cards come from established sellers."},{"h":"4. Shipping rules"},{"p":"Graded cards should always ship with tracking. On Slabs & Singles, graded cards always ship with a tracked label, and you can buy the label right from the order at the carrier''s price. Every listing ships free to the buyer, so build shipping into your price: a slab in a small box by USPS Ground Advantage usually costs about $6–9."},{"h":"How to price a graded card"},{"list":["Look up recent sold prices for the same card, same grader and same grade. A PSA 9 and a PSA 10 of the same card can be worlds apart.","Price against sold prices, not asking prices; asking prices run high.","Graders aren''t interchangeable: the same grade from different companies often sells for different amounts.","If you''re unsure, list at a fair Buy It Now price with Best Offer on, or run an auction with a reserve."]},{"h":"How to photograph a slab"},{"list":["Shoot the front and back straight on, so the label and cert number are readable.","Avoid glare: turn off overhead lights and shoot near a window, or tilt the slab slightly.","Show any scratches on the case honestly. Buyers will see them anyway."]},{"h":"How to pack a graded card"},{"list":["Put the slab in a soft sleeve or bubble pouch so the case doesn''t scratch.","Sandwich it between two pieces of cardboard, or use a slab-sized box.","Add bubble wrap so it can''t move, and ship in a padded mailer or box with tracking.","Ship within 3 business days of payment and add the tracking number to the order."]},{"links":[{"label":"Packing guide","href":"/help/packing"}]},{"h":"Selling a lot of graded cards?"},{"p":"Card shops, breakers and dealers can open a free business store with their own page, categories, store sales and followers. If you manage your collection in FireCardManager, you can list cards to Slabs & Singles in one click, with photos, grades and cert numbers filled in for you."},{"links":[{"label":"Start selling","href":"/sell"},{"label":"Business stores","href":"/help/stores"},{"label":"Connect FireCardManager","href":"/help/firecardmanager"}]},{"note":"Fees and shipping costs change over time. The fee figures above come from our live fee schedule; check other sites'' current fee pages before you compare."}]'::jsonb, 'published', '2026-11-05T12:00:00Z'),
('free-shipping-trading-card-singles', 'Free Shipping on Trading Card Singles: How It Works and Why It Saves You Money', 'Why free shipping matters for trading card singles, how sellers ship cards safely, and how to buy Pokémon, Magic and sports singles with no shipping fees.', 'free shipping trading card singles', 'Anyone who buys cheap singles knows the feeling: the card is $1.50, and shipping is $4.99. For collectors filling binders and players finishing decks, shipping can cost more than the cards. Here''s how free shipping on trading card singles works, how cards ship safely, and how to get the most for your money.', '[{"h":"Every card on Slabs & Singles ships free"},{"p":"There''s no minimum order and no shipping line at checkout. The price on the listing is the price you pay, plus sales tax where it applies. That goes for Pokémon, Magic: The Gathering, Yu-Gi-Oh!, One Piece, Lorcana and other trading card games, sports cards and non-sport cards alike, all shipped to US addresses."},{"links":[{"label":"Shop trading card game singles","href":"/tcg"},{"label":"Shop sports cards","href":"/sports"},{"label":"Cards under $5","href":"/search?max_price=5&sort=price_asc"}]},{"h":"How do sellers ship for free?"},{"p":"Sellers build shipping into their price and choose the cheapest safe way to send each order:"},{"list":["One raw card up to $20 can travel in a stamped envelope, protected in a penny sleeve and a toploader or card saver. That costs the seller a single stamp, which is why cheap singles can ship free.","Graded cards, cards over $20 and orders of more than one card ship in a padded mailer or box with a tracked label.","Sellers ship within 3 business days of payment."]},{"h":"Is a stamped envelope safe for a trading card?"},{"p":"For an inexpensive single, packed properly, yes. The card goes in a penny sleeve and a rigid toploader, taped closed so it can''t slide out, usually between cardboard. A nonmachinable stamp is used for thick or rigid packages so the envelope isn''t run through sorting rollers. Sellers can add USPS letter tracking, so you can see when the envelope is scanned along the way."},{"p":"Envelopes have no delivery confirmation, which is why they''re only for raw cards up to $20. Anything more valuable ships with a tracked label."},{"h":"Get more for your money"},{"list":["Buy several cards from one seller. They ship together in one package, and many sellers give a multi-card discount, taken off automatically in your cart.","Watch for store sales: business stores can run sales of up to 50% off, shown with the regular price crossed out.","Make an offer on listings marked “or Best Offer.”","Save a search to be notified when a card you want is listed."]},{"h":"Compare the total, not the sticker price"},{"p":"When you compare sites, add shipping to every card. A $1.00 card with $4.50 shipping is a $5.50 card. With free shipping the comparison is simple: the listed price is the total."},{"h":"Buying safely"},{"list":["Pay on the site. Stripe processes the payment, and your card issuer''s purchase protection applies.","Never pay a seller through Venmo, Zelle, Cash App or PayPal Friends & Family.","Check the condition (NM, LP, MP, HP or DMG) and the photos of the front and back.","If an order has a problem, message the seller from the order first."]},{"h":"For sellers: pricing with free shipping"},{"p":"Add your shipping cost to your price. For a raw card under $20 that''s usually one stamp: 82¢ for a Forever stamp, or $1.31 for a nonmachinable stamp for thick cards and very rigid toploaders. For everything else, a USPS Ground Advantage label for a bubble mailer is usually about $5–7. The listing form estimates your payout, shipping included, before you list."},{"links":[{"label":"Shipping rules","href":"/help/shipping"},{"label":"Packing guide","href":"/help/packing"}]}]'::jsonb, 'published', '2026-11-05T12:00:00Z'),
('how-to-sell-tcg-singles-online', 'How to Sell TCG Singles Online: Pokémon, Magic, Yu-Gi-Oh! and More', 'Step-by-step guide to selling TCG singles online: pricing Pokémon, Magic and Yu-Gi-Oh! cards, grading condition, listing fast, shipping cheaply and keeping more of each sale.', 'how to sell TCG singles online', 'A binder of extra Pokémon, Magic or Yu-Gi-Oh! cards can be worth real money, but only if you can sell the singles without fees and shipping eating the profit. This guide walks through how to sell TCG singles online, from sorting and pricing to listing, packing and getting paid.', '[{"h":"Step 1: Sort out what''s worth listing"},{"p":"Most commons sell for pennies; the money is in a smaller set of cards. Pull these first:"},{"list":["Rares, ultra rares, secret rares, full arts and alternate arts.","Holo, reverse holo and foil versions of playable or popular cards.","Cards that are played in current formats (playables sell steadily).","Older cards: 1st Edition, early sets and out-of-print products.","Anything graded, or worth grading."]},{"p":"Bulk commons and uncommons are usually better sold as a lot than one card at a time."},{"h":"Step 2: Identify each card exactly"},{"p":"Two copies of the same card can sell for very different prices depending on the printing. Note the set, the card number, the rarity and the finish (normal, holo, reverse holo, foil, 1st Edition). For Yu-Gi-Oh!, the set code printed on the card (like LOB-EN001) identifies the exact printing."},{"h":"Step 3: Grade the condition honestly"},{"list":["Near Mint (NM): looks fresh from the pack, at most a tiny flaw.","Lightly Played (LP): minor edge or corner wear, light scratches.","Moderately Played (MP): noticeable wear, but no major damage.","Heavily Played (HP): heavy wear, creases or clouding.","Damaged (DMG): tears, water damage, writing or major creases."]},{"p":"When in doubt, list one grade lower. Buyers who get a card better than described leave great feedback."},{"h":"Step 4: Price it from recent sales"},{"p":"Price from what the card has actually sold for recently, not from the highest asking price you can find. For Pokémon, Magic and Yu-Gi-Oh!, TCGplayer''s market price, built from recent sales, is a good starting point. Price competitively for cards that sell often; for rare cards, list at a fair Buy It Now price with Best Offer turned on."},{"h":"Step 5: Take good photos"},{"list":["Photograph the front and back of the actual card, not a stock image.","Use even light without glare. Foils and holos are easiest to shoot near a window.","Show any damage clearly."]},{"h":"Step 6: Choose where to sell"},{"p":"General marketplaces have huge audiences but high fees for cheap cards: on a $3 single, a fee over 13% plus a per-order fee and shipping can leave you with almost nothing. On Slabs & Singles:"},{"list":["Listing is free.","One fee per card sold: {fee.flat} for cards up to {fee.threshold}, then {fee.percent} capped at {fee.cap}.","Stripe''s card processing, usually 2.9% + 30¢ per order, comes out of your own Stripe balance, and buyers pay you directly.","Every card ships free to the buyer, so buyers compare prices fairly and cheap singles still sell."]},{"links":[{"label":"Selling fees in detail","href":"/help/fees"}]},{"h":"Step 7: List quickly"},{"list":["List one card at a time from the seller hub, choosing the game, set, card number, condition and price.","Upload a CSV to list hundreds of cards at once.","Use FireCardManager TCG to scan cards, identify and price them with AI and market prices, and publish to Slabs & Singles in one click."]},{"h":"Step 8: Ship cheaply and safely"},{"list":["One raw card up to $20: penny sleeve, toploader, tape the top, and mail it in an envelope with a stamp (82¢ Forever, or $1.31 nonmachinable for thick packages).","Higher-value cards, graded cards and multi-card orders: a bubble mailer with a tracked label, which you can buy from the order.","Ship within 3 business days, and add tracking when you have it."]},{"links":[{"label":"Packing guide","href":"/help/packing"}]},{"h":"Step 9: Sell more per order"},{"list":["Turn on a multi-card discount. Buyers who add several of your cards ship in one package, so pass the savings on.","Add friends and regulars to your trusted buyer list so they can choose envelope shipping for one raw card up to $100.","If you''re a shop or a full-time seller, open a free business store with your own categories, store sales and followers."]},{"h":"Step 10: Build your reputation"},{"p":"Describe cards honestly, ship on time and answer messages quickly. New sellers start with a $20 limit per card and earn $250 and then $1,000 limits as they build feedback. Badges, from Bronze at 10 sales to Diamond at 5,000, and Top Rated show buyers you''re a seller they can trust."},{"links":[{"label":"Start selling TCG singles","href":"/sell"},{"label":"Seller levels","href":"/help/seller-levels"},{"label":"Seller badges","href":"/help/seller-badges"}]}]'::jsonb, 'published', '2026-11-05T12:00:00Z');
